VALID_TECHNIQUES = {
    'T1059.001', 'T1059.003', 'T1053.005', 'T1569.002',
    'T1003.001', 'T1003.002', 'T1078', 'T1110', 'T1087',
    'T1087.002', 'T1482', 'T1021', 'T1021.002'
}

def validate_response(response: dict) -> dict:
    """Validate LLM response and flag hallucinated MITRE IDs."""
    if 'mitre_technique' in response:
        techniques = response['mitre_technique']
        if isinstance(techniques, str):
            techniques = [techniques]
        valid = [t for t in techniques if t in VALID_TECHNIQUES]
        invalid = [t for t in techniques if t not in VALID_TECHNIQUES]
        if invalid:
            response['validation_warnings'] = f'Invalid MITRE IDs: {invalid}'
            response['confidence'] = 'LOW'
        response['mitre_technique'] = valid
    return response
